def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        # Fill the entire row
        grid[row, :] = 5
    elif kind == 1:
        # Fill top row
        grid[0, :] = 5
    return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

def goal_value(history):
    last_grid = np.array(history.frames[-1], dtype=np.int8)
    # Check if entire row 0 is filled (value 5)
    if np.all(last_grid[0, :] == 5):
        return 1.0
    return 0.0
